// Написан autotest-writer вручную (запасной путь), проверен прогоном 12.11.2026. spec: .qa/e2e/specs/onboarding-photos.md 1.1–1.4
// Шаг «בחר/י את התמונות שלך» (/photos) на существующем аккаунте new02 («QA П2 0011», 3 фото: лицо + 2 заглушки).
// Новые регистрации не создаются (нужен OTP). Удаление фото НЕ нажимается (вернуть фото с лицом нечем) — только «ביטול».
// 1.4 меняет главное фото и возвращает исходное в finally. Всё @data: общий аккаунт + одноразовый refresh-токен.
import { test, expect } from '../../fixtures';
import type { Page } from '@playwright/test';
import { saveSession } from '../_shared/session';
import { captureApi, restGet } from '../_shared/api';

async function openPhotos(p: Page, width = 390, height = 844) {
  await p.setViewportSize({ width, height });
  await p.goto('/photos');
  await expect(p.getByText('בחר/י את התמונות שלך')).toBeVisible();
  await expect(p.getByRole('button', { name: 'ראשית', exact: true })).toBeVisible();
}

const mainTile = (p: Page) => p.getByRole('button', { name: 'ראשית', exact: true });
const smallTiles = (p: Page) => p.getByRole('button', { name: 'הפיכה לראשית', exact: true });
const srcOf = (p: Page, tile: ReturnType<typeof mainTile>) => tile.locator('img').first().getAttribute('src');

test.describe('Онбординг — шаг фото (new02)', () => {
  test.describe.configure({ mode: 'serial', timeout: 120_000 });

  test('Сетка 390: главная 228×300 и малые 112×145 с белой рамкой 3px, «ראשית» справа сверху, без X, пустые ячейки «+», «המשך» активна при ≥2 @iphone @data (#aabd1e)', async ({ asUser }) => {
    const p = await asUser('new02');
    try {
      await openPhotos(p);
      // Рамка — у обёртки кнопки: размеры и 3px белая граница (Р6, Р8).
      const frame = (loc: ReturnType<typeof mainTile>) => loc.evaluate((e) => {
        const f = e.parentElement!;
        const r = f.getBoundingClientRect();
        const s = getComputedStyle(f);
        return { w: Math.round(r.width), h: Math.round(r.height), bw: s.borderTopWidth, bc: s.borderTopColor, right: r.right, top: r.top };
      });
      const main = await frame(mainTile(p));
      expect([main.w, main.h], 'главная 228×300').toEqual([228, 300]);
      expect(main.bw, 'рамка главной 3px').toBe('3px');
      expect(main.bc, 'рамка белая').toMatch(/^rgba?\(255, 255, 255/);
      await expect(smallTiles(p)).toHaveCount(2);
      for (const t of await smallTiles(p).all()) {
        const s = await frame(t);
        expect([s.w, s.h], 'малая 112×145').toEqual([112, 145]);
      }
      // «ראשית» — в правом верхнем углу главной (~10px от краёв) (Р6).
      const lbl = (await mainTile(p).getByText('ראשית', { exact: true }).boundingBox())!;
      expect(main.right - (lbl.x + lbl.width), 'отступ «ראשית» справа').toBeLessThanOrEqual(24);
      expect(lbl.y - main.top, 'отступ «ראשית» сверху').toBeLessThanOrEqual(20);
      // Без X на фото (Р8): кнопки сетки — только «ראשית», «הפיכה לראשית», «הוספת תמונה».
      await expect(p.getByRole('button', { name: /^(X|×|✕|הסרה|מחיקה|הסרת תמונה)$/ })).toHaveCount(0);
      await expect(p.getByRole('button', { name: 'הוספת תמונה', exact: true })).toHaveCount(3);
      // Пустые ячейки 112×145 (Р6).
      for (const t of await p.getByRole('button', { name: 'הוספת תמונה', exact: true }).all()) {
        const b = (await t.boundingBox())!;
        expect([Math.round(b.width), Math.round(b.height)], 'пустая ячейка 112×145').toEqual([112, 145]);
      }
      // 3 фото ≥ 2 → «המשך» активна (Р2); подзаголовок «לפחות 2».
      await expect(p.getByText(/לפחות 2/)).toBeVisible();
      await expect(p.getByRole('button', { name: 'המשך' })).toBeEnabled();
      // Заголовок в одну строку на 375 (Р2).
      await openPhotos(p, 375, 667);
      const h = await p.getByText('בחר/י את התמונות שלך', { exact: true }).evaluate((e) => {
        const lh = parseFloat(getComputedStyle(e).lineHeight) || 0;
        return { h: e.getBoundingClientRect().height, lh };
      });
      if (h.lh) expect(h.h, 'заголовок в одну строку на 375').toBeLessThan(h.lh * 1.5);
    } finally {
      await saveSession(p, 'new02');
    }
  });

  test('Тап по главной и долгий тап по малой — лист «מה לעשות עם התמונה?» с «הסרת תמונה»/«ביטול»; «ביטול» ничего не меняет @iphone @data (#aabd1e)', async ({ asUser }) => {
    const p = await asUser('new02');
    try {
      await openPhotos(p);
      const before = [await srcOf(p, mainTile(p)), ...(await Promise.all((await smallTiles(p).all()).map((t) => srcOf(p, t))))];
      // Тап по главной → лист (Р8).
      await mainTile(p).click();
      const sheet = p.getByRole('dialog');
      await expect(sheet.getByText('מה לעשות עם התמונה?')).toBeVisible();
      await expect(sheet.getByRole('button', { name: /הסרת תמונה/ })).toBeVisible();
      await sheet.getByRole('button', { name: 'ביטול', exact: true }).click();
      await expect(p.getByRole('dialog')).toHaveCount(0);
      // Долгий тап по малой → тот же лист (+ «הפיכה לראשית») (Р8). Держим, пока лист не появится.
      const b = (await smallTiles(p).first().boundingBox())!;
      await p.mouse.move(b.x + b.width / 2, b.y + b.height / 2);
      await p.mouse.down();
      await expect(sheet.getByText('מה לעשות עם התמונה?')).toBeVisible();
      await p.mouse.up();
      await expect(sheet.getByRole('button', { name: /הסרת תמונה/ })).toBeVisible();
      await expect(sheet.getByRole('button', { name: /הפיכה לראשית/ })).toBeVisible();
      await sheet.getByRole('button', { name: 'ביטול', exact: true }).click();
      await expect(p.getByRole('dialog')).toHaveCount(0);
      // Ничего не удалено и порядок прежний.
      const after = [await srcOf(p, mainTile(p)), ...(await Promise.all((await smallTiles(p).all()).map((t) => srcOf(p, t))))];
      expect(after).toEqual(before);
    } finally {
      await saveSession(p, 'new02');
    }
  });

  test('Не-картинка в «הוספת תמונה» — «משהו השתבש. נסו שוב.», экран живой, фото не добавилось @iphone @data (#aabd1e)', async ({ asUser }) => {
    const p = await asUser('new02');
    try {
      await openPhotos(p);
      const chooser = p.waitForEvent('filechooser');
      await p.getByRole('button', { name: 'הוספת תמונה', exact: true }).first().click();
      await (await chooser).setFiles({ name: 'QA-AUTO-not-image.txt', mimeType: 'text/plain', buffer: Buffer.from('QA-AUTO not an image') });
      await expect(p.getByText('משהו השתבש. נסו שוב.')).toBeVisible();
      await expect(smallTiles(p)).toHaveCount(2);
      await expect(p.getByRole('button', { name: 'הוספת תמונה', exact: true })).toHaveCount(3);
      await expect(p.getByRole('button', { name: 'המשך' })).toBeEnabled();
    } finally {
      await saveSession(p, 'new02');
    }
  });

  test('Тап по малой делает её главной и это сохраняется после перезагрузки (затем возврат) @iphone @data (#aabd1e)', async ({ asUser }) => {
    const p = await asUser('new02');
    // Исходный порядок фото — с сервера; возврат — тем же PATCH profiles, что делает приложение (токен new02).
    const api = await captureApi(p, '/photos');
    const photosOf = async () => {
      const r = await restGet(api, `profiles?id=eq.${api.userId}&select=photos`);
      expect(r.status(), await r.text()).toBe(200);
      return ((await r.json())[0]?.photos ?? []) as string[];
    };
    const original = await photosOf();
    expect(original.length, 'у new02 ≥ 3 фото').toBeGreaterThanOrEqual(3);
    try {
      await openPhotos(p);
      await expect.poll(() => srcOf(p, mainTile(p)), { message: 'главная = первое фото с сервера' }).toBe(original[0]);
      const target = await srcOf(p, smallTiles(p).first());
      const saved = p.waitForResponse((r) => r.url().includes('/rest/v1/profiles') && r.request().method() === 'PATCH');
      await smallTiles(p).first().click();
      expect((await saved).ok(), 'PATCH profiles 2xx').toBeTruthy();
      await expect.poll(() => srcOf(p, mainTile(p)), { message: 'выбранная стала главной' }).toBe(target);
      // Сохраняется на сервере и после перезагрузки (Р1).
      expect((await photosOf())[0], 'на сервере первое фото — выбранное').toBe(target);
      await p.reload();
      await expect.poll(() => srcOf(p, mainTile(p)), { message: 'после перезагрузки главная — выбранная' }).toBe(target);
    } finally {
      const now = await photosOf().catch(() => [] as string[]);
      if (JSON.stringify(now) !== JSON.stringify(original)) {
        await p.request.patch(`${api.base}/rest/v1/profiles?id=eq.${api.userId}`, {
          headers: { apikey: api.apikey, Authorization: api.auth, 'Content-Type': 'application/json', Prefer: 'return=minimal' },
          data: { photos: original },
          failOnStatusCode: false,
        });
      }
      const back = await photosOf().catch(() => [] as string[]);
      await saveSession(p, 'new02');
      expect(back, `порядок фото new02 возвращён (иначе вручную на /photos сделать главным ${original[0]})`).toEqual(original);
    }
  });
});
